contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single-call test: sendMoney must not increase depositsCount nor c's balance
    function run(address target, uint amount) public payable {
        require(target != address(0));
        // record before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // single top-level state-changing call
        bool reverted;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // general rule: depositsCount does not increase and c.balance does not increase
        assert(afterDeposits == beforeDeposits && afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

